{
  "subject_definitions": [
    { "name": "<Subject 1>", "look": "<这个人的长相与装造，一段话，全片每一格都照抄这一段措辞>" }
  ],
  "summary": "<整片的一句话：这是什么片子、什么调性、画面靠什么连起来>",
  "shots": [
    {
      "title": "<这个镜头要拍什么，一句话>",
      "seconds": 12,
      "storyboards": [
        {
          "prompt": "<第一格的文生图提示词：主体是谁、在做什么、环境是什么、光从哪来、构图怎么摆、材质与质感。要能独立画出这一张。>",
          "motion": "<从这一格走到下一格，画面里发生了什么：主体怎么动、镜头朝哪个方向去、什么在变。>"
        },
        {
          "prompt": "<第二格的文生图提示词，同上要求>",
          "motion": "<第二格走到第三格的那一段>"
        },
        {
          "prompt": "<最后一格的文生图提示词，同上要求>",
          "tail": "<这一格要明确收在什么画面上（选填；不写就以下一格的画面为尾帧）>"
        }
      ]
    }
  ]
}
